	zip.Describe("github.com/hanzoai/cloud/apps/train POST /v1/train/artifacts", zip.Doc{
		Description: "Records rows the org is about to upload, named by the\nSHA-256 of their bytes, and answers the same grant an executor's artifact\ngets: a presigned PUT S3 accepts only with that checksum and length, encrypted\nunder the org's key — a PUT per 64 MiB part over 64 MiB — or stored: true when\nthe org already holds those bytes. A job names them as `dataset.uri`\n`artifact:<sha256>`, and its create reads the upload back before it is\naccepted. Storage is billed by the GB-month while the org keeps them, so an\nupload is refused 402/503 when the uploader's wallet cannot pay a month of\nkeeping these bytes with what it already keeps in the org and what the org has\npending.",
		Fields: map[string]string{
			"part.headers":       "Headers must be sent verbatim; the signature covers them.",
			"part.number":        "Number orders the part from 1.",
			"part.offset":        "Offset is the part's first byte in the object.",
			"part.size":          "Size is the part's byte count.",
			"part.url":           "URL is the presigned address to PUT the range to.",
			"registerOut.sha256": "SHA256 names the artifact.",
			"registerOut.stored": "Stored says the org already holds these bytes: nothing to upload.",
			"registerOut.upload": "Upload is the grant to PUT the bytes, when they are not stored.",
			"upload.expires":     "Expires is when the grant stops being accepted, unix seconds.",
			"upload.headers":     "Headers must be sent verbatim with the single PUT; the signature covers them.",
			"upload.method":      "Method is PUT.",
			"upload.parts":       "Parts are the object's consecutive byte ranges, each PUT to its own address.",
			"upload.url":         "URL is the presigned address of a single PUT; empty when Parts is given.",
			"uploadIn.kind":      "Kind is dataset: JSON Lines rows a job reads as `artifact:<sha256>`.",
			"uploadIn.name":      "Name labels it.",
			"uploadIn.sha256":    "SHA256 is the hex digest of the bytes.",
			"uploadIn.size":      "Size is the byte count.",
		},
		Example: json.RawMessage(`{"kind":"dataset","name":"tickets","sha256":"…","size":1048576}`),
	})
	zip.Describe("github.com/hanzoai/cloud/apps/train POST /v1/train/clients", zip.Doc{
		Description: "Loads base_model on the engine with a LoRA adapter and answers\nthe client, loading; poll it until ready. The wire is the engine's own\ncreate → forward_backward → optim_step → sample → save_weights loop, so a loop\nwritten against the engine runs here with only the path changed. The\ncapability fields are validated as a job's are: adaptation is lora, protect is\nrefused, and kai is not a client base. A client holds a model in the memory every\norg's inference shares, so only a SuperAdmin creates one until the engine isolates\norgs. An org holds at most TRAIN_CLIENTS live clients and the engine at most\nTRAIN_ENGINE_CLIENTS across every org; past that the answer is 503 engine_full.",
		Fields: map[string]string{
			"Adaptation.alpha":           "Alpha is an adapter's scale.",
			"Adaptation.basis":           "Basis is a basis artifact, by sha256 or `basis://<base>/<name>`.",
			"Adaptation.chose":           "Chose is what auto resolved to and why; absent unless auto was asked.",
			"Adaptation.mode":            "Mode is full, readout (the head alone, over the frozen base), lora, qlora,\nbasis or auto.",
			"Adaptation.rank":            "Rank is an adapter's rank, or how many of a basis's directions are used.",
			"Adaptation.residual_rank":   "ResidualRank is the rank of an orthonormal residual learned beside a basis's\ncoefficients; 0 trains the coefficients alone.",
			"Adaptation.sources":         "Sources are lora artifacts (sha256) a basis is built from, in place of Basis.",
			"Adaptation.targets":         "Targets are the modules an adapter or a basis attaches to.",
			"Budget.accuracy":            "Accuracy is the largest accuracy drop allowed.",
			"Budget.ece":                 "ECE is the largest calibration-error rise allowed.",
			"Chose.mode":                 "Mode is the mode the job runs.",
			"Chose.why":                  "Why says what decided it.",
			"Projection.strength":        "Strength is λ in [0, 1]; absent is 1, the whole of P g removed.",
			"Protect.budget":             "Budget bounds the regression per protected suite.",
			"Protect.capabilities":       "Capabilities are capability artifacts, by sha256.",
			"Protect.distillation":       "Distillation adds KL to the base's answers on a preservation set drawn from\nthe suites.",
			"Protect.projection":         "Projection projects every update off the protected directions — the suites'\ngradient subspace at the base and each named capability's subspace — by its\nstrength; absent is no projection.",
			"Protect.suites":             "Suites are capabilities the base already has, by suite.",
			"createClientIn.adaptation":  "Adaptation is lora, the one mode clients run; its shape is lora_config.",
			"createClientIn.base_model":  "BaseModel is a model the engine loads: a Hugging Face repo id or a local path.",
			"createClientIn.lora_config": "LoraConfig is the adapter's shape, as the engine's wire takes it.",
			"createClientIn.protect":     "Protect is refused: clients protect nothing yet.",
		},
		Example: json.RawMessage(`{"base_model":"HuggingFaceTB/SmolLM2-135M","lora_config":{"rank":16,"alpha":32}}`),
	})
